// clang-format off
// This file is generated by ECMake (`ec_add_benchmarks` with the nanobench
// framework). Do not edit by hand.
//
// Tiny benchmark registry for nanobench, using the same shape as Google Benchmark:
//
//   #include <ec_nanobench.h>
//
//   static void BM_Containers(ankerl::nanobench::Bench& bench) {
//     bench.relative(true);
//     bench.run("std::vector", [&] { /* ... */ });
//     bench.run("std::list",   [&] { /* ... */ });
//   }
//   BENCHMARK(BM_Containers);
//
// The benchmark is registered under the name of the function ("BM_Containers"),
// which is also the title of `bench`.
// Benchmarks can be registered in any number of source files.
// Unlike Google Benchmark, `BENCHMARK` returns nothing to chain options on
// (e.g. `->Arg(8)`): nanobench is configured through `bench`.
// Requires C++11 (as nanobench itself).
//
// The generated `main()` calls `ecmake::nanobench::run(argc, argv)`, which
// accepts the following Google Benchmark flags:
//   --benchmark_filter=<regex>    only run the benchmarks whose name matches
//                                 (prefix with `-` to exclude, `all` for all)
//   --benchmark_list_tests        list the benchmark names and exit
//   --benchmark_dry_run           run each benchmark for a single iteration
//   --benchmark_out=<file>        write the results to <file> (Google Benchmark JSON)
//   --benchmark_out_format=json   the only supported format
// With NO_MAIN, call `ecmake::nanobench::run(argc, argv)` from your own `main()`.

#ifndef ECMAKE_HG_EC_NANOBENCH
#define ECMAKE_HG_EC_NANOBENCH

#include <nanobench.h>

namespace ecmake {
namespace nanobench {

/// @brief The signature of a registered benchmark function.
using BenchmarkFunction = void (*)(::ankerl::nanobench::Bench& bench);

/// @brief Registers a benchmark (prefer using `BENCHMARK`).
/// @param name The name of the benchmark (must outlive the program, e.g. a literal)
/// @param function The benchmark function
void register_benchmark(const char* name, BenchmarkFunction function);

/// @brief Registers a benchmark when constructed (used by `BENCHMARK`).
/// Using an object with a constructor (rather than e.g. a `bool` initialized
/// by a function call) avoids unused variable warnings, without attributes.
struct Registrar {
  Registrar(const char* name, BenchmarkFunction function) {
    register_benchmark(name, function);
  }
};

/// @brief Runs the registered benchmarks, according to the command line flags.
/// @param argc The argument count, as passed to `main()`
/// @param argv The arguments, as passed to `main()`
/// @return The exit code to return from `main()`
int run(int argc, char** argv);

} // namespace nanobench
} // namespace ecmake

#ifdef BENCHMARK
#  error "`BENCHMARK` is already defined"
#endif

#define ECMAKE_NANOBENCH_CONCAT_IMPL(a, b) a##b
#define ECMAKE_NANOBENCH_CONCAT(a, b) ECMAKE_NANOBENCH_CONCAT_IMPL(a, b)

#define ECMAKE_NANOBENCH_REGISTER(FUNCTION, ID)                                                   \
  static const ::ecmake::nanobench::Registrar ECMAKE_NANOBENCH_CONCAT(ec_benchmark_registrar_, ID)( \
    #FUNCTION, &FUNCTION)

/// @brief Registers `void FUNCTION(ankerl::nanobench::Bench&)` under the name of the function:
/// `BENCHMARK(BM_Function);`
#define BENCHMARK(FUNCTION) ECMAKE_NANOBENCH_REGISTER(FUNCTION, __COUNTER__)

#endif // !ECMAKE_HG_EC_NANOBENCH

// clang-format on
